(()=>{
 const add=window.POLIS_ADD_SYSTEM;if(!add)return;
 add({id:'machiavelli',prefix:'ma',author:'Nicolás Maquiavelo',work:'El Príncipe + Discursos',workId:'prince',icon:'🦊',tagline:'Verità effettuale, virtù, fortuna, conflicto y libertad republicana',lessons:[
  {title:'Verità effettuale: mirar la política como funciona',hook:'Maquiavelo rompe con los principados imaginados para estudiar mecanismos efectivos de adquisición, conservación y pérdida del poder.',body:'La verità effettuale della cosa obliga a analizar conductas, incentivos, fuerzas y consecuencias reales. No significa abandonar toda evaluación normativa, sino rechazar reglas políticas que ignoran cómo actúan efectivamente humanos y Estados.',relation:['experiencia histórica','verità effettuale','mecanismos de poder','juicio político'],terms:[['verità effettuale','','verdad efectiva'],['stato','','Estado / dominio político'],['esperienza','','experiencia'],['ordine','','orden / institución']],quote:{original:'andare drieto alla verità effettuale della cosa',translation:'«Ir detrás de la verdad efectiva de la cosa».',source:'Il Principe XV',note:'El contraste es con la imaginazione de repúblicas y principados que nunca existieron.'},example:'Una regla moral puede ser admirable y, sin embargo, producir el efecto contrario si todos los rivales explotan unilateralmente su cumplimiento.',tip:'Primero describí el mecanismo; después juzgá la acción.',discovery:{scenario:'Un consejero diseña política suponiendo que todos cumplirán promesas aunque sabe que sus rivales las rompen sistemáticamente.',question:'¿Qué le reprocharía Maquiavelo?',options:['Ignorar la verità effettuale','Falta de ley natural','Exceso de soberanía popular'],answer:0,reveal:'La política debe partir de cómo operan efectivamente actores y circunstancias.'},check:{prompt:'¿Qué exige la verità effettuale?',options:['Analizar la política efectiva y sus consecuencias','Aceptar todo lo existente como bueno','Eliminar toda historia'],answer:0}},
  {title:'Virtù y fortuna',hook:'El resultado político surge de la interacción entre capacidad de acción y contingencia.',body:'Virtù no equivale simplemente a virtud moral cristiana. Es capacidad de comprender la ocasión, adaptar medios, imponer forma a circunstancias y sostener un orden. Fortuna designa la parte contingente e imprevisible de los acontecimientos.',relation:['fortuna','occasione','virtù','resultado político'],terms:[['virtù','','capacidad política efectiva'],['fortuna','','fortuna / contingencia'],['occasione','','ocasión'],['necessità','','necesidad']],quote:{original:'la fortuna sia arbitra della metà delle azioni nostre',translation:'«La fortuna sea árbitra de la mitad de nuestras acciones».',source:'Il Principe XXV',note:'La otra parte queda abierta a la acción, aunque nunca bajo control total.'},example:'Una crisis puede destruir a un gobernante rígido y ofrecer una ocasión a otro capaz de adaptar instituciones y estrategia.',tip:'No traduzcas virtù como simple bondad moral.',discovery:{scenario:'Dos gobernantes enfrentan la misma crisis; uno repite rutinas y el otro adapta medios rápidamente.',question:'¿Qué concepto explica la diferencia?',options:['Virtù','Lex naturalis','Pietas'],answer:0,reveal:'Virtù es capacidad de responder a ocasión y fortuna.'},check:{prompt:'¿Cómo se relacionan virtù y fortuna?',options:['La capacidad política actúa dentro de contingencias que no controla por completo','La fortuna elimina toda agencia','Virtù significa obediencia pasiva'],answer:0}},
  {title:'Imparare a potere essere non buono',hook:'La conservación del Estado puede obligar a actuar contra virtudes convencionales.',body:'El príncipe debe aprender a poder no ser bueno cuando la necessità lo exige. La tesis no celebra el mal por sí mismo: introduce una tensión entre moral privada, responsabilidad política y consecuencias para la seguridad del Estado.',relation:['norma moral ordinaria','necessità','elección de medios','conservación del Estado'],terms:[['necessità','','necesidad política'],['non buono','','no bueno'],['mantenere lo stato','','mantener el Estado'],['prudenza','','prudencia']],quote:{original:'imparare a potere essere non buono',translation:'«Aprender a poder no ser bueno».',source:'Il Principe XV',note:'La formulación es condicional: usar o no esa capacidad según la necesidad.'},example:'Un gobernante puede enfrentar una conspiración donde la indulgencia absoluta destruya el orden que debe proteger.',tip:'La pregunta maquiaveliana es qué efectos produce una virtud cuando se aplica sin prudencia.',discovery:{scenario:'Un gobernante mantiene una promesa aun cuando sabe que el rival la rompió y que cumplirla destruirá su Estado.',question:'¿Qué tensión aparece?',options:['Moral ordinaria versus necessità política','Ley eterna versus natural','Pluralidad versus natalidad'],answer:0,reveal:'La razón política puede exigir medios que una ética ordinaria desaprueba.'},check:{prompt:'¿Qué significa “poder no ser bueno”?',options:['Conservar capacidad de usar medios duros cuando la necesidad política lo exige','Ser cruel siempre','Negar toda moral'],answer:0}},
  {title:'Apariencia, reputación y credibilidad',hook:'La política ocurre en un mundo donde la mayoría juzga por signos visibles.',body:'El príncipe necesita parecer poseer virtudes porque la reputación estructura obediencia y alianzas. Pero debe conservar flexibilidad para actuar de otro modo cuando sea necesario. La apariencia es un componente objetivo del poder político.',relation:['apariencia pública','reputación','expectativas','capacidad de gobierno'],terms:[['parere','','parecer'],['reputazione','','reputación'],['fede','','fe / fidelidad'],['simulazione','','simulación']],quote:{original:'ognuno vede quello che tu pari, pochi sentono quello che tu se’',translation:'«Todos ven lo que pareces; pocos perciben lo que eres».',source:'Il Principe XVIII',note:'La frase explica por qué la imagen pública tiene efectos políticos reales.'},example:'Un gobierno puede perder capacidad de negociación si nadie cree sus amenazas aunque materialmente tenga recursos.',tip:'Reputación no es adorno: cambia expectativas de otros actores.',discovery:{scenario:'Un gobernante dispone de fuerza, pero todos creen que nunca cumplirá una amenaza.',question:'¿Qué recurso político está deteriorado?',options:['Credibilidad y reputación','Autarkeia','Voluntad general'],answer:0,reveal:'La percepción pública modifica el poder efectivo.'},check:{prompt:'¿Por qué importa parecer virtuoso?',options:['Porque la reputación estructura obediencia y expectativas','Porque apariencia y realidad son idénticas','Porque elimina la necesidad de fuerza'],answer:0}},
  {title:'Crueldades bien usadas',hook:'Maquiavelo distingue violencia concentrada para estabilizar de violencia repetida que reproduce odio e inseguridad.',body:'Las crudeltà bene usate se ejecutan de una vez por necesidad de seguridad y luego cesan, permitiendo producir beneficios y estabilidad. Las mal usadas crecen con el tiempo. El criterio es político y consecuencial, no una aprobación moral irrestricta.',relation:['crisis de seguridad','violencia concentrada','estabilización','reducción de coerción'],terms:[['crudeltà bene usate','','crueldades bien usadas'],['sicurtà','','seguridad'],['odio','','odio'],['benefizi','','beneficios']],quote:{original:'crudeltà bene usate ... si fanno a uno tratto',translation:'«Crueldades bien usadas ... se hacen de una vez».',source:'Il Principe VIII',note:'El pasaje distingue concentración inicial de violencia y su prolongación acumulativa.'},example:'Una purga interminable genera temor y odio distintos de una acción excepcional seguida por reglas estables.',tip:'Analizá secuencia temporal y efectos, no solo intensidad.',discovery:{scenario:'Un régimen usa violencia creciente cada mes y nunca produce seguridad estable.',question:'¿Cómo clasificaría Maquiavelo esa dinámica?',options:['Crueldades mal usadas','Virtù perfecta','Orden republicano'],answer:0,reveal:'La violencia que se multiplica y reproduce inseguridad fracasa incluso bajo el criterio maquiaveliano.'},check:{prompt:'¿Qué caracteriza las crueldades “bien usadas”?',options:['Concentración por necesidad seguida de estabilización','Violencia creciente indefinida','Ausencia de objetivo político'],answer:0}},
  {title:'Fundar órdenes nuevos',hook:'Crear instituciones nuevas es una de las tareas más difíciles porque perjudica intereses existentes.',body:'El fundador enfrenta enemigos entre quienes se beneficiaban del viejo orden y apoyo incierto entre quienes podrían beneficiarse del nuevo. Virtù incluye organizar fuerza y reglas capaces de hacer durable una innovación.',relation:['vecchio ordine','resistencia de intereses','fondatore','nuovi ordini'],terms:[['fondatore','','fundador'],['nuovi ordini','','órdenes nuevos'],['armi proprie','','armas propias'],['profeti armati','','profetas armados']],quote:{original:'tutti e profeti armati vinsono',translation:'«Todos los profetas armados vencieron».',source:'Il Principe VI',note:'“Armado” expresa capacidad propia de sostener la innovación, no solo armamento literal.'},example:'Una reforma profunda fracasa si depende enteramente de actores que perderán poder con su éxito.',tip:'El problema fundador es transformar innovación en institución durable.',discovery:{scenario:'Una reforma amenaza privilegios existentes y solo cuenta con entusiasmo difuso de beneficiarios futuros.',question:'¿Qué problema describe?',options:['La dificultad de fundar nuovi ordini','La paz perpetua','La ley natural'],answer:0,reveal:'Los defensores del viejo orden suelen ser más organizados que los beneficiarios potenciales del nuevo.'},check:{prompt:'¿Qué necesita un fundador exitoso?',options:['Capacidad propia para sostener e institucionalizar el nuevo orden','Solo buenas intenciones','Evitar todo conflicto'],answer:0}},
  {title:'Tumultos entre grandi y popolo',hook:'En los Discursos, el conflicto social puede producir libertad en lugar de ser solo enfermedad.',body:'Roma fue libre no a pesar de los conflictos entre plebe y Senado, sino en parte gracias a ellos. Grandi desean mandar; popolo desea no ser dominado. Instituciones que canalizan ese antagonismo pueden generar leyes favorables a la libertà.',relation:['humores sociales','tumulti','instituciones','libertà'],terms:[['grandi','','grandes / élites'],['popolo','','pueblo'],['tumulti','','tumultos / conflictos'],['libertà','','libertad política']],quote:{original:'i tumulti ... furono prima cagione del tenere libera Roma',translation:'«Los tumultos ... fueron causa primera de mantener libre a Roma».',source:'Discorsi I.4',note:'Maquiavelo rompe con la idea de que toda discordia civil destruye necesariamente la república.'},example:'Un veto popular institucionalizado puede limitar a una élite sin eliminar el conflicto que le dio origen.',tip:'No confundas orden con ausencia de antagonismo.',discovery:{scenario:'Una república contiene conflicto persistente entre élites que quieren mandar y pueblo que no quiere ser dominado.',question:'¿Debe eliminarse todo conflicto?',options:['No: puede institucionalizarse productivamente','Sí, siempre','Solo mediante un príncipe absoluto'],answer:0,reveal:'Los humores opuestos pueden producir instituciones de libertad.'},check:{prompt:'¿Qué papel pueden cumplir los tumulti?',options:['Generar instituciones que protejan la libertad','Destruir siempre toda república','Eliminar los humores sociales'],answer:0}},
  {title:'Libertad republicana, ordini y corrupción',hook:'La república libre necesita instituciones capaces de canalizar conflicto y regenerarse frente a corrupción.',body:'La libertà no depende solo de virtud individual. Requiere ordini y leggi que distribuyan poder, permitan acusación y contengan ambiciones. Cuando costumbres e instituciones dejan de corresponderse, la república entra en corrupción y necesita renovación.',relation:['humores','ordini e leggi','libertà','renovación contra corrupción'],terms:[['ordini','','órdenes / instituciones'],['leggi','','leyes'],['corruzione','','corrupción'],['libertà','','libertad republicana']],quote:{original:'tutte le cose del mondo hanno il termine della vita loro',translation:'«Todas las cosas del mundo tienen el término de su vida».',source:'Discorsi III.1',note:'Las repúblicas necesitan mecanismos de renovación para evitar decadencia institucional.'},example:'Mantener reglas pensadas para una sociedad ya transformada puede convertir una constitución antes funcional en una fuente de corrupción.',tip:'Cerrá el sistema conectando conflicto, instituciones, virtù colectiva y renovación.',discovery:{scenario:'Una república conserva leyes antiguas aunque cambió por completo la estructura social y nadie puede corregir abusos.',question:'¿Qué riesgo aparece?',options:['Corruzione','Autarkeia','Paz perpetua'],answer:0,reveal:'Las instituciones deben renovarse para seguir canalizando humores y ambiciones.'},check:{prompt:'¿Qué sostiene la libertad republicana?',options:['Ordini y leyes capaces de canalizar conflicto y renovarse','Ausencia completa de conflicto','Virtud privada sin instituciones'],answer:0}}
 ]});

 add({id:'spinoza',prefix:'sp',author:'Baruch Spinoza',work:'Ética + Tratado teológico-político + Tratado político',workId:'spinoza-tp',icon:'🔷',tagline:'Conatus, afectos, derecho-potencia, multitud y libertad',lessons:[
  {title:'Conatus: perseverar en el ser',hook:'La política spinozista parte de seres afectados que buscan perseverar, no de sujetos moralmente puros.',body:'Cada cosa se esfuerza por perseverar en su ser. En humanos, el conatus adopta formas de deseo y se modula por afectos. La política debe comprender esas potencias efectivas en vez de imaginar hombres como deberían ser.',relation:['conatus','affectus','desiderium','conducta política'],terms:[['conatus','','esfuerzo por perseverar'],['affectus','','afecto'],['desiderium','','deseo'],['potentia','','potencia / capacidad']],quote:{original:'Unaquaeque res ... in suo esse perseverare conatur.',translation:'«Cada cosa se esfuerza por perseverar en su ser».',source:'Ethica III, prop. 6',note:'El conatus es base ontológica de la teoría de afectos y poder.'},example:'Miedo y esperanza pueden organizar obediencia política sin que los ciudadanos hayan deducido racionalmente una obligación moral abstracta.',tip:'Antes de hablar de derecho, identificá potencias y afectos.',discovery:{scenario:'Una teoría política supone que el miedo, deseo y esperanza desaparecerán cuando se promulgue una buena ley.',question:'¿Qué objeción spinozista aparece?',options:['Ignora la dinámica efectiva de los afectos','Carece de monarquía','Tiene demasiada libertad'],answer:0,reveal:'La política debe trabajar con la naturaleza afectiva humana.'},check:{prompt:'¿Qué es conatus?',options:['Esfuerzo de cada cosa por perseverar en su ser','Mandato del soberano','Contrato civil'],answer:0}},
  {title:'Ius naturale sive potentia',hook:'El derecho natural alcanza hasta donde alcanza la potencia efectiva de cada ser.',body:'Spinoza rompe con una lectura moralizada del derecho natural. En estado de naturaleza, ius y potentia coinciden: cada individuo tiene tanto derecho como capacidad efectiva de actuar. El derecho no es una norma separada de la potencia.',relation:['potentia individual','ius naturale','acción efectiva','límites reales'],terms:[['ius naturale','','derecho natural'],['potentia','','potencia'],['natura','','naturaleza'],['jus sive potentia','','derecho como potencia']],quote:{original:'jus uniuscujusque eo usque se extendit quo ejus potentia',translation:'«El derecho de cada uno se extiende hasta donde se extiende su potencia».',source:'Tractatus theologico-politicus XVI',note:'La equivalencia derecho-potencia distingue a Spinoza del iusnaturalismo normativo clásico.'},example:'Un pez tiene “derecho” natural a nadar y comer según su potencia; no porque una ley moral se lo conceda.',tip:'No proyectes derechos subjetivos modernos directamente sobre ius naturale spinozista.',discovery:{scenario:'Una persona reclama un derecho natural que no puede ejercer ni sostener bajo ninguna relación efectiva.',question:'¿Qué preguntaría Spinoza?',options:['Cuál es su potentia real','Quién escribió la constitución','Cuál es su clase social'],answer:0,reveal:'El ius naturale está medido por potencia efectiva.'},check:{prompt:'¿Cómo relaciona Spinoza ius y potentia?',options:['El derecho natural se extiende con la potencia efectiva','Son opuestos absolutos','El derecho elimina la potencia'],answer:0}},
  {title:'Razón, utilidad y cooperación',hook:'La razón muestra que individuos aumentan su potencia cooperando con otros.',body:'Aunque el derecho natural no desaparece moralmente, la experiencia enseña que los humanos aislados son débiles y vulnerables. Bajo guía racional, encuentran útil combinar fuerzas y construir reglas comunes.',relation:['vulnerabilidad individual','utilitas','cooperación','potencia común'],terms:[['ratio','','razón'],['utilitas','','utilidad'],['auxilium mutuum','','ayuda mutua'],['communis utilitas','','utilidad común']],quote:{original:'homini nihil homine utilius',translation:'«Nada es más útil al hombre que el hombre».',source:'Ethica IV, prop. 18 schol.',note:'La cooperación puede explicarse por incremento de potencia, no por altruismo abstracto.'},example:'Dos individuos que coordinan defensa poseen más capacidad de conservarse que cada uno aisladamente.',tip:'La sociabilidad surge de una economía de potencias y utilidades.',discovery:{scenario:'Dos personas vulnerables pueden duplicar su capacidad de defensa si cooperan.',question:'¿Qué muestra este caso?',options:['La utilidad de componer potencias','La inutilidad de toda comunidad','La necesidad de obediencia pasiva'],answer:0,reveal:'Cooperar puede aumentar la potencia de cada integrante.'},check:{prompt:'¿Por qué puede ser racional la cooperación?',options:['Porque compone potencias y aumenta utilidad común','Porque elimina todo deseo','Porque reduce toda libertad a cero'],answer:0}},
  {title:'Imperium y potencia de la multitud',hook:'El poder político no flota por encima de la sociedad: expresa una potencia colectiva.',body:'En el Tratado político, el derecho del Estado se define por la potentia multitudinis. Imperium es la organización relativamente estable de esa potencia común. Un gobernante incapaz de sostener obediencia efectiva pierde poder aunque conserve títulos formales.',relation:['potencias individuales','multitudo','potentia multitudinis','imperium'],terms:[['multitudo','','multitud'],['potentia multitudinis','','potencia de la multitud'],['imperium','','Estado / poder político'],['summa potestas','','poder supremo']],quote:{original:'hoc jus, quod multitudinis potentia definitur, Imperium appellari solet',translation:'«Este derecho, definido por la potencia de la multitud, suele llamarse Estado».',source:'Tractatus politicus II.17',note:'El poder estatal se mide por relaciones efectivas de potencia colectiva.'},example:'Un gobierno con decretos formales pero sin obediencia, administración ni fuerza efectiva tiene un imperium debilitado.',tip:'Pensá el Estado como composición institucional de potencia social.',discovery:{scenario:'Un monarca conserva título legal, pero ejército, ciudades y funcionarios ya no obedecen.',question:'¿Conserva intacta su potentia?',options:['No','Sí, el título basta','Solo si posee riqueza'],answer:0,reveal:'La potencia política depende de relaciones efectivas, no solo de derecho formal.'},check:{prompt:'¿Qué define el imperium?',options:['La potencia organizada de la multitud','Un contrato moral irrevocable','La virtud privada del príncipe'],answer:0}},
  {title:'Afectos y estabilidad institucional',hook:'Un buen régimen no exige que la multitud deje de ser afectiva; organiza afectos para reducir causas de rebelión.',body:'Spinoza critica instituciones que dependen de virtud extraordinaria. El diseño político debe hacer que gobernantes y gobernados tengan incentivos y afectos compatibles con la conservación del Estado.',relation:['afectos ordinarios','diseño institucional','interés en conservar orden','estabilidad'],terms:[['metus','','miedo'],['spes','','esperanza'],['affectus communes','','afectos comunes'],['instituta','','instituciones']],quote:{original:'hominum vitia ... non ridere, non lugere, neque detestari, sed intelligere',translation:'«No reír, llorar ni detestar los vicios humanos, sino comprenderlos».',source:'Tractatus politicus I.4',note:'La política se presenta como ciencia de causas humanas reales.'},example:'Una constitución más robusta es la que funciona con ciudadanos comunes, no solo con santos excepcionalmente racionales.',tip:'Sustituí moralización por comprensión causal.',discovery:{scenario:'Una constitución solo funciona si todos renuncian espontáneamente a ambición, miedo y rivalidad.',question:'¿Qué objeción spinozista surge?',options:['Diseño antropológicamente irreal','Falta de religión oficial','Exceso de comercio'],answer:0,reveal:'Las instituciones deben operar con afectos humanos efectivos.'},check:{prompt:'¿Qué busca el realismo institucional spinozista?',options:['Organizar afectos e intereses en vez de exigir virtud imposible','Eliminar toda emoción','Reemplazar instituciones por moral privada'],answer:0}},
  {title:'Libertas philosophandi',hook:'La estabilidad del Estado puede ser compatible con amplia libertad de pensar y decir.',body:'El Tratado teológico-político sostiene que intentar dominar completamente las mentes es imposible y contraproducente. La libertad de filosofar puede coexistir con obediencia civil y favorecer una república pacífica.',relation:['libertad de pensamiento','expresión','obediencia en actos','paz civil'],terms:[['libertas philosophandi','','libertad de filosofar'],['libertas sentiendi','','libertad de pensar'],['obedientia','','obediencia'],['pax','','paz']],quote:{original:'in libera republica unicuique et sentire quae velit ... licet',translation:'«En una república libre se permite a cada uno pensar lo que quiera».',source:'Tractatus theologico-politicus XX',note:'Spinoza distingue libertad de juicio y regulación de acciones.'},example:'El ciudadano puede criticar públicamente una ley mientras la cumple y busca reformarla por medios institucionales.',tip:'Separá control de actos y pretensión de controlar pensamientos.',discovery:{scenario:'Un Estado intenta prohibir incluso pensar críticamente sobre sus leyes.',question:'¿Qué problema vería Spinoza?',options:['Es imposible y políticamente contraproducente','Garantiza estabilidad perfecta','Aumenta la razón'],answer:0,reveal:'Las mentes no se gobiernan como los cuerpos.'},check:{prompt:'¿Qué protege libertas philosophandi?',options:['Libertad de pensar y argumentar compatible con orden civil','Derecho a desobedecer cualquier acción','Silencio obligatorio'],answer:0}},
  {title:'Democracia y conservación del derecho natural',hook:'La democracia se aproxima a la condición natural porque nadie entrega completamente su potencia a otro individuo.',body:'En el régimen democrático, cada uno transfiere poder al conjunto del que sigue formando parte. Spinoza lo considera especialmente compatible con libertad y con la conservación de la racionalidad pública.',relation:['individuos','cesión al conjunto','participación en potencia común','democracia'],terms:[['democratia','','democracia'],['universa multitudo','','multitud entera'],['libertas','','libertad'],['aequalitas','','igualdad']],quote:{original:'imperium Democraticum ... maxime naturale',translation:'«El gobierno democrático ... es el más natural».',source:'Tractatus theologico-politicus XVI',note:'“Natural” significa aquí cercano a una composición común de potencias.'},example:'Transferir poder a una asamblea de la que todos participan difiere de quedar sometido al arbitrio personal de otro individuo.',tip:'Democracia se conecta con composición de potencia, no con romanticismo moral.',discovery:{scenario:'Ciudadanos obedecen decisiones del cuerpo común del que participan y pueden deliberar.',question:'¿Qué régimen aproxima mejor esta estructura?',options:['Democracia','Tiranía personal','Oligarquía cerrada'],answer:0,reveal:'La democracia organiza la potencia común sin personificarla totalmente en uno.'},check:{prompt:'¿Por qué la democracia es “más natural”?',options:['Porque compone la potencia de todos en un cuerpo común','Porque elimina toda ley','Porque vuelve a la soledad natural'],answer:0}},
  {title:'El fin del Estado es la libertad',hook:'La seguridad no culmina en obediencia pasiva: debe permitir desarrollar potencia racional.',body:'Spinoza afirma que el fin de la república es libertas. El Estado estabiliza condiciones en las que las personas pueden vivir sin miedo, cultivar razón y usar cuerpo y mente con seguridad.',relation:['seguridad','reducción del miedo','uso de razón','libertas'],terms:[['finis Reipublicae','','fin de la república'],['libertas','','libertad'],['securitas','','seguridad'],['ratio','','razón']],quote:{original:'Finis ergo Reipublicae revera libertas est.',translation:'«El fin de la república es verdaderamente la libertad».',source:'Tractatus theologico-politicus XX',note:'La seguridad funciona como condición de una vida más libre, no como fin autosuficiente.'},example:'Un orden que evita guerra civil pero destruye toda capacidad de pensar y actuar racionalmente queda por debajo del fin político spinozista.',tip:'Cerrá el sistema: potencia común debe producir seguridad que amplíe libertad.',discovery:{scenario:'Un Estado es estable pero mantiene a todos bajo miedo permanente y censura total.',question:'¿Realiza plenamente su fin?',options:['No','Sí, estabilidad basta','Solo si es monarquía'],answer:0,reveal:'La república se justifica en último término por libertad.'},check:{prompt:'¿Cuál es el fin de la república?',options:['Libertad','Dominación por sí misma','Gloria militar'],answer:0}}
 ]});

 add({id:'locke',prefix:'lo',author:'John Locke',work:'Segundo tratado sobre el gobierno',workId:'second-treatise',icon:'🔐',tagline:'Derechos naturales, propiedad, consentimiento, trust y resistencia',lessons:[
  {title:'Estado de naturaleza: libertad e igualdad',hook:'Locke comienza con personas libres e iguales, no con súbditos nacidos bajo mando político.',body:'El state of nature es un estado de perfecta libertad e igualdad dentro de los límites de la ley natural. No equivale necesariamente a guerra: existe obligación moral antes del gobierno civil.',relation:['natural freedom','natural equality','law of nature','state of nature'],terms:[['state of nature','','estado de naturaleza'],['perfect freedom','','perfecta libertad'],['equality','','igualdad'],['natural law','','ley natural']],quote:{original:'a State of perfect Freedom ... A State also of Equality',translation:'«Un estado de perfecta libertad ... y también de igualdad».',source:'Second Treatise §4',note:'Libertad no significa licencia ilimitada.'},example:'Dos personas sin gobierno común siguen estando obligadas a no destruir arbitrariamente vida o libertad ajena.',tip:'No conviertas automáticamente el estado de naturaleza lockeano en guerra hobbesiana.',discovery:{scenario:'Dos individuos no tienen juez común, pero reconocen deberes de no dañarse.',question:'¿Es ya necesariamente guerra?',options:['No','Sí siempre','Solo si poseen propiedad'],answer:0,reveal:'Estado de naturaleza y estado de guerra son conceptos distintos en Locke.'},check:{prompt:'¿Qué caracteriza el estado de naturaleza?',options:['Libertad e igualdad bajo ley natural','Guerra permanente','Obediencia a soberano absoluto'],answer:0}},
  {title:'La razón como ley natural',hook:'La igualdad natural genera límites recíprocos que la razón puede conocer.',body:'Reason enseña que, siendo todos iguales e independientes, nadie debe dañar a otro en vida, salud, libertad o posesiones. Cada individuo posee inicialmente poder ejecutivo para hacer cumplir esa ley.',relation:['igualdad natural','reason','deber de no dañar','ejecución de ley natural'],terms:[['Reason','','razón'],['Law of Nature','','ley de naturaleza'],['life','','vida'],['liberty','','libertad']],quote:{original:'Reason, which is that Law, teaches all Mankind',translation:'«La razón, que es esa ley, enseña a toda la humanidad».',source:'Second Treatise §6',note:'La obligación natural precede a la legislación estatal.'},example:'Castigar una agresión en estado de naturaleza pretende ejecutar una ley previa, no inventar moralidad desde cero.',tip:'El gobierno no crea todos los derechos; institucionaliza su protección.',discovery:{scenario:'Antes de cualquier Estado, una persona mata por diversión a un inocente.',question:'¿Puede ser injusto para Locke?',options:['Sí','No, sin Estado nada es injusto','Solo si existe contrato'],answer:0,reveal:'La ley natural obliga antes del poder civil.'},check:{prompt:'¿Qué enseña la razón natural?',options:['No dañar derechos básicos de iguales','Obedecer cualquier conquistador','Eliminar propiedad'],answer:0}},
  {title:'Property: persona, trabajo y apropiación',hook:'Locke explica cómo algo común puede convertirse legítimamente en propiedad individual.',body:'Cada hombre tiene property in his own person. Al mezclar trabajo con un recurso común, agrega algo propio y puede apropiárselo, bajo límites iniciales de no desperdicio y dejar suficiente y tan bueno para otros.',relation:['property in person','labour','appropriation','proviso'],terms:[['property','','propiedad / derechos propios'],['labour','','trabajo'],['appropriation','','apropiación'],['enough and as good','','suficiente y tan bueno']],quote:{original:'every Man has a Property in his own Person',translation:'«Todo hombre tiene una propiedad en su propia persona».',source:'Second Treatise §27',note:'“Property” puede tener sentido amplio y no solo referirse a bienes materiales.'},example:'Recolectar frutos mediante trabajo puede volverlos propios antes de que exista un registro estatal.',tip:'Seguí la cadena persona → trabajo → apropiación → límites.',discovery:{scenario:'Una persona recolecta y transforma un recurso común mediante su trabajo.',question:'¿Qué fundamento de apropiación aparece?',options:['Labour','Conquista','Mayoría política'],answer:0,reveal:'El trabajo conecta la persona con el recurso apropiado.'},check:{prompt:'¿Qué papel cumple el trabajo?',options:['Fundamenta apropiación de recursos comunes bajo límites','Anula toda propiedad','Solo crea impuestos'],answer:0}},
  {title:'Dinero, consentimiento e desigualdad',hook:'La introducción del dinero permite acumular más allá de los límites inmediatos del consumo.',body:'Como el dinero no se pudre y es aceptado por consentimiento, posibilita acumulación duradera y amplía desigualdades de posesión. Locke presenta esa transformación como vinculada a una convención social previa al Estado.',relation:['bienes perecederos','money','consent','acumulación desigual'],terms:[['money','','dinero'],['consent','','consentimiento'],['spoilage','','desperdicio'],['unequal possession','','posesión desigual']],quote:{original:'Men have agreed to a disproportionate and unequal Possession of the Earth',translation:'«Los hombres han acordado una posesión desproporcionada y desigual de la tierra».',source:'Second Treatise §50',note:'El dinero modifica los límites prácticos de acumulación.'},example:'Guardar cien manzanas hasta que se pudran viola el límite de desperdicio; convertir excedentes en dinero cambia el problema.',tip:'La teoría de propiedad cambia al introducir una institución monetaria consensual.',discovery:{scenario:'Un bien no perecedero es aceptado por todos y permite guardar valor por décadas.',question:'¿Qué cambia?',options:['La escala posible de acumulación','La ley natural desaparece','La igualdad política se vuelve imposible'],answer:0,reveal:'El dinero permite acumulación desigual más extensa.'},check:{prompt:'¿Qué efecto tiene el dinero?',options:['Hace posible acumulación duradera y desigual mediante consentimiento','Elimina propiedad','Impide intercambio'],answer:0}},
  {title:'Los inconvenientes del estado de naturaleza',hook:'El problema no es ausencia de moralidad sino falta de instituciones imparciales y eficaces.',body:'En estado de naturaleza faltan una ley estable y conocida en aplicación común, un juez imparcial y un poder capaz de ejecutar sentencias. El interés propio hace inseguro el ejercicio individual de derechos.',relation:['derechos naturales','juez parcial','ejecución incierta','sociedad política'],terms:[['known law','','ley conocida'],['indifferent judge','','juez imparcial'],['executive power','','poder ejecutivo'],['inconveniences','','inconvenientes']],quote:{original:'there wants an established, settled, known Law',translation:'«Falta una ley establecida, fija y conocida».',source:'Second Treatise §124',note:'Locke enumera luego juez imparcial y poder de ejecución.'},example:'Todos reconocen un derecho, pero cada parte juzga su propio conflicto y aplica castigos distintos.',tip:'El Estado resuelve defectos institucionales, no crea al individuo desde cero.',discovery:{scenario:'Dos personas aceptan la misma norma pero cada una se declara juez de su propia causa.',question:'¿Qué inconveniente aparece?',options:['Falta de juez imparcial','Falta de propiedad natural','Exceso de soberanía'],answer:0,reveal:'El interés propio hace frágil la ejecución privada de ley natural.'},check:{prompt:'¿Por qué entrar en sociedad política?',options:['Para proteger derechos mediante ley, juez y ejecución comunes','Para renunciar a todos los derechos','Para crear desigualdad natural'],answer:0}},
  {title:'Consentimiento, mayoría y cuerpo político',hook:'Nadie puede quedar sometido legítimamente al poder político sin consentimiento.',body:'Al consentir formar una community, individuos crean un cuerpo político que debe poder actuar. La regla de mayoría deriva de esa necesidad de producir una voluntad operativa del cuerpo común.',relation:['consent','community','majority','political society'],terms:[['consent','','consentimiento'],['community','','comunidad política'],['majority','','mayoría'],['political society','','sociedad política']],quote:{original:'no one can be ... subjected to the Political Power of another, without his own Consent',translation:'«Nadie puede ser sometido al poder político de otro sin su propio consentimiento».',source:'Second Treatise §95',note:'El consentimiento funda la incorporación inicial al cuerpo político.'},example:'Si cada decisión requiriera unanimidad permanente, el cuerpo político podría quedar incapaz de actuar.',tip:'Consentimiento funda el cuerpo; mayoría permite que opere.',discovery:{scenario:'Cien personas acuerdan crear una comunidad pero exigen unanimidad para cada decisión ordinaria.',question:'¿Qué problema aparece?',options:['El cuerpo puede volverse incapaz de actuar','Se fortalece automáticamente','Desaparece toda libertad'],answer:0,reveal:'Locke conecta incorporación por consentimiento y regla de mayoría.'},check:{prompt:'¿Qué legitima la incorporación al cuerpo político?',options:['Consentimiento','Nacimiento bajo cualquier gobernante','Conquista'],answer:0}},
  {title:'Legislative power como trust',hook:'El poder legislativo es supremo dentro del gobierno, pero no es propiedad privada de los legisladores.',body:'El legislative actúa fiduciariamente para fines definidos: preservación de la sociedad y de property. Debe gobernar por leyes generales, no arbitrarias, y no puede transferir libremente el poder recibido del pueblo.',relation:['pueblo','trust','legislative','preservación de property'],terms:[['legislative power','','poder legislativo'],['trust','','fideicomiso / confianza política'],['property','','vida, libertad y bienes'],['prerogative','','prerrogativa']],quote:{original:'the Legislative being only a Fiduciary Power',translation:'«El legislativo es solo un poder fiduciario».',source:'Second Treatise §149',note:'La supremacía legislativa queda limitada por el fin del trust.'},example:'Un parlamento no puede convertir legítimamente la autorización recibida para proteger derechos en licencia para confiscarlos arbitrariamente.',tip:'Supremacía no equivale a poder ilimitado.',discovery:{scenario:'Una legislatura usa su competencia para apropiarse permanentemente de todos los bienes de la población.',question:'¿Qué se rompe?',options:['El trust','La ley natural de igualdad','La regla de mayoría como tal'],answer:0,reveal:'El poder delegado deja de perseguir el fin para el que fue confiado.'},check:{prompt:'¿Qué significa que el legislativo sea fiduciario?',options:['Que ejerce poder confiado para fines limitados','Que es propietario del pueblo','Que no puede legislar'],answer:0}},
  {title:'Dissolution y derecho de resistencia',hook:'Cuando el gobierno rompe el trust, puede disolverse la obligación hacia quienes usurpan el poder.',body:'Si gobernantes intentan destruir derechos o alterar el legislativo sin autorización, se ponen en estado de guerra con el pueblo. La resistencia no es derecho a rebelarse por cualquier desacuerdo, sino respuesta a ruptura persistente del trust.',relation:['abuso grave','breach of trust','dissolution of government','resistance'],terms:[['breach of trust','','ruptura del trust'],['dissolution','','disolución'],['resistance','','resistencia'],['appeal to Heaven','','apelación al cielo']],quote:{original:'the People are at liberty to provide for themselves',translation:'«El pueblo queda en libertad de proveer por sí mismo».',source:'Second Treatise §220',note:'La disolución del gobierno no equivale necesariamente a disolución de la sociedad.'},example:'Un ejecutivo cancela permanentemente elecciones y usa fuerza para impedir que el legislativo se reúna.',tip:'El derecho de resistencia protege el orden de consentimiento contra usurpación.',discovery:{scenario:'Un gobernante destruye el legislativo y confisca derechos para mantenerse indefinidamente.',question:'¿Qué diagnóstico lockeano corresponde?',options:['Breach of trust','Ejercicio normal de prerrogativa','Estado civil perfecto'],answer:0,reveal:'La usurpación puede disolver el gobierno y reactivar poder del pueblo.'},check:{prompt:'¿Cuándo aparece resistencia legítima?',options:['Ante ruptura grave del trust y ataque a derechos','Ante cualquier ley impopular','Solo ante invasión extranjera'],answer:0}}
 ]});

 add({id:'rousseau',prefix:'ro',author:'Jean-Jacques Rousseau',work:'Discurso sobre la desigualdad + El contrato social',workId:'social-contract',icon:'🌿',tagline:'Desigualdad, pacto, voluntad general, soberanía y libertad',lessons:[
  {title:'Amour de soi y pitié',hook:'Rousseau reconstruye al humano natural antes de instituciones complejas para distinguir necesidades básicas de pasiones sociales.',body:'El hombre natural se mueve por amour de soi, orientado a conservación, y pitié, repugnancia a ver sufrir. No es todavía el ciudadano racional ni el individuo competitivo de la sociedad desarrollada.',relation:['autoconservación','amour de soi','pitié','sociabilidad limitada'],terms:[['amour de soi','','amor de sí natural'],['pitié','','piedad / compasión'],['homme naturel','','hombre natural'],['perfectibilité','','perfectibilidad']],quote:{original:'l’amour de soi-même ... est un sentiment naturel',translation:'«El amor de sí es un sentimiento natural».',source:'Discours sur l’inégalité, nota XV',note:'Rousseau distingue amour de soi de amour-propre socialmente comparativo.'},example:'Buscar alimento para conservarse no implica todavía querer superar en prestigio a otros.',tip:'Separá necesidades naturales de pasiones nacidas de comparación social.',discovery:{scenario:'Una persona busca sobrevivir sin medir su valor por la posición de otros.',question:'¿Qué afecto describe mejor?',options:['Amour de soi','Amour-propre','Libido dominandi'],answer:0,reveal:'El amour de soi está ligado a conservación, no a comparación.'},check:{prompt:'¿Qué caracteriza al amour de soi?',options:['Autoconservación no comparativa','Competencia por prestigio','Obediencia política'],answer:0}},
  {title:'Amour-propre, propiedad y desigualdad',hook:'La desigualdad moral se desarrolla históricamente cuando comparación, propiedad y dependencia reorganizan deseos.',body:'Con sociedad, división del trabajo y propiedad aparece amour-propre: necesidad de reconocimiento relativo. El célebre “primer cercado” simboliza un proceso histórico de institucionalización de desigualdades, no un instante documental literal.',relation:['comparación social','amour-propre','propiedad','desigualdad institucional'],terms:[['amour-propre','','amor propio comparativo'],['propriété','','propiedad'],['inégalité morale','','desigualdad moral/política'],['dépendance','','dependencia']],quote:{original:'Le premier qui, ayant enclos un terrain, s’avisa de dire: Ceci est à moi',translation:'«El primero que cercó un terreno y dijo: esto es mío».',source:'Discours sur l’inégalité, II',note:'La escena funciona como condensación genealógica de la propiedad institucionalizada.'},example:'Querer alimento y querer un automóvil más prestigioso que el del vecino responden a estructuras de deseo distintas.',tip:'La crítica de desigualdad es genealógica: explica cómo se producen nuevas pasiones.',discovery:{scenario:'Una comunidad empieza a medir valor personal por riqueza visible y reconocimiento ajeno.',question:'¿Qué pasión se expande?',options:['Amour-propre','Amour de soi solamente','Conatus sin afectos'],answer:0,reveal:'La comparación social transforma deseos y dependencias.'},check:{prompt:'¿Qué distingue amour-propre?',options:['Dependencia comparativa de la mirada ajena','Conservación biológica simple','Ley natural racional'],answer:0}},
  {title:'El problema del pacto legítimo',hook:'El Contrato social busca una forma de asociación que proteja a cada uno sin destruir su libertad.',body:'El problema es encontrar una asociación en la que fuerza común defienda persona y bienes, mientras cada miembro obedece a una voluntad de la que forma parte. La legitimidad exige transformar dependencia personal en autonomía cívica.',relation:['vulnerabilidad social','association','protección común','libertad civil'],terms:[['association','','asociación'],['pacte social','','pacto social'],['liberté','','libertad'],['force commune','','fuerza común']],quote:{original:'Trouver une forme d’association qui défende et protège ... chaque associé',translation:'«Encontrar una forma de asociación que defienda y proteja a cada asociado».',source:'Du contrat social I.6',note:'El resto de la fórmula exige que cada uno siga siendo libre al unirse a todos.'},example:'Un pacto que entrega a todos a un amo puede producir seguridad pero no resuelve el problema rousseauniano de libertad legítima.',tip:'La pregunta no es solo cómo crear poder, sino cómo hacerlo compatible con libertad.',discovery:{scenario:'Una comunidad obtiene seguridad sometiéndose irrevocablemente a la voluntad privada de un señor.',question:'¿Resuelve el problema de Rousseau?',options:['No','Sí completamente','Solo si el señor es rico'],answer:0,reveal:'La asociación legítima debe preservar libertad como autolegislación colectiva.'},check:{prompt:'¿Qué debe combinar el pacto?',options:['Protección común y libertad','Dominación privada y silencio','Riqueza y conquista'],answer:0}},
  {title:'Alienación total y cuerpo soberano',hook:'Cada uno entrega sus derechos a la comunidad entera, no a otro individuo particular.',body:'La cláusula fundamental es alienación total de cada asociado con todos sus derechos a la comunidad. Como la condición es igual para todos, nadie gana interés en hacerla onerosa para otro. Surge un cuerpo moral colectivo: el souverain.',relation:['alienación a todos','igualdad de condición','cuerpo colectivo','souverain'],terms:[['aliénation totale','','alienación total'],['souverain','','soberano colectivo'],['corps moral','','cuerpo moral'],['citoyen','','ciudadano']],quote:{original:'chacun de nous met en commun sa personne et toute sa puissance',translation:'«Cada uno pone en común su persona y todo su poder».',source:'Du contrat social I.6',note:'La entrega es al cuerpo común del que cada miembro forma parte.'},example:'Entregar poder a todos bajo la misma condición difiere de transferirlo a un príncipe exterior al pacto.',tip:'El soberano rousseauniano es el pueblo como cuerpo legislador.',discovery:{scenario:'Todos se someten por igual a reglas que ellos mismos forman como cuerpo común.',question:'¿Qué entidad aparece?',options:['Souverain','Tirano','Juez natural individual'],answer:0,reveal:'El pacto constituye un cuerpo moral colectivo.'},check:{prompt:'¿A quién se alienan los derechos?',options:['A la comunidad entera','A un monarca privado','A ningún cuerpo común'],answer:0}},
  {title:'Volonté générale y soberanía',hook:'La voluntad general mira al interés común y no es simple suma de preferencias privadas.',body:'La souveraineté es ejercicio de volonté générale. Es inalienable e indivisible porque no puede representarse la voluntad como si fuera una propiedad transferible. La volonté de tous suma intereses particulares; la general requiere considerar el común.',relation:['ciudadanos','deliberación sobre interés común','volonté générale','soberanía'],terms:[['volonté générale','','voluntad general'],['volonté de tous','','voluntad de todos'],['souveraineté','','soberanía'],['intérêt commun','','interés común']],quote:{original:'la souveraineté ... n’étant que l’exercice de la volonté générale',translation:'«La soberanía no es sino el ejercicio de la voluntad general».',source:'Du contrat social II.1',note:'Voluntad general y unanimidad empírica no son sinónimos.'},example:'Todos pueden votar por ventajas privadas y producir una suma de intereses que no expresa una regla general justa.',tip:'Preguntá por el objeto de la voluntad, no solo por el número de votos.',discovery:{scenario:'Una mayoría aprueba un beneficio exclusivo para sí cargando todo el costo a una minoría.',question:'¿Basta que sea mayoría para ser volonté générale?',options:['No','Sí siempre','Solo si es unánime'],answer:0,reveal:'La generalidad depende de orientación al interés común.'},check:{prompt:'¿Qué define la volonté générale?',options:['Orientación al interés común del cuerpo político','Suma automática de preferencias','Voluntad privada del gobernante'],answer:0}},
  {title:'Ley y Legislador',hook:'La ley es general en su fuente y en su objeto, pero crear un pueblo capaz de legislar exige formación política.',body:'La loi expresa la voluntad general sobre materias generales. El Législateur no es soberano ni gobernante: propone instituciones y ayuda a formar costumbres, pero no puede sustituir al pueblo en la autoridad legislativa.',relation:['volonté générale','objet général','loi','formation du peuple'],terms:[['loi','','ley'],['Législateur','','Legislador'],['mœurs','','costumbres'],['objet général','','objeto general']],quote:{original:'les lois ne sont proprement que les conditions de l’association civile',translation:'«Las leyes son propiamente las condiciones de la asociación civil».',source:'Du contrat social II.6',note:'La ley legítima no es decreto particular contra una persona.'},example:'Una norma que nombra y castiga a un enemigo individual no posee la generalidad característica de la ley.',tip:'Separá soberano legislador, Legislador fundador y gobierno ejecutivo.',discovery:{scenario:'Una asamblea dicta una norma dirigida a una sola persona por nombre.',question:'¿Es loi en sentido fuerte?',options:['No','Sí siempre','Solo si el castigo es pequeño'],answer:0,reveal:'La ley tiene objeto general.'},check:{prompt:'¿Qué hace el Législateur?',options:['Propone instituciones y forma costumbres sin sustituir la soberanía popular','Gobierna como soberano permanente','Ejecuta todas las leyes'],answer:0}},
  {title:'Soberano y gobierno no son lo mismo',hook:'El pueblo soberano legisla; el gouvernement ejecuta y administra.',body:'Rousseau distingue voluntad legislativa del cuerpo soberano y fuerza ejecutiva del gobierno. El gobierno es un cuerpo intermedio encargado de aplicar leyes y puede adoptar forma democrática, aristocrática o monárquica sin cambiar dónde reside la soberanía.',relation:['souverain','loi','gouvernement','exécution'],terms:[['gouvernement','','gobierno ejecutivo'],['magistrats','','magistrados'],['souverain','','soberano'],['puissance exécutive','','poder ejecutivo']],quote:{original:'Qu’est-ce donc que le Gouvernement? Un corps intermédiaire',translation:'«¿Qué es, pues, el gobierno? Un cuerpo intermedio».',source:'Du contrat social III.1',note:'La forma del ejecutivo no determina por sí sola la titularidad de soberanía.'},example:'Un pueblo soberano puede encargar ejecución cotidiana a pocos magistrados sin transferirles la voluntad general.',tip:'No leas “monarquía” ejecutiva como soberanía monárquica en sentido hobbesiano.',discovery:{scenario:'El pueblo dicta leyes generales y encarga a cinco magistrados ejecutarlas.',question:'¿Dónde reside la soberanía?',options:['En el pueblo','En los cinco magistrados','En el ejército'],answer:0,reveal:'Gobierno y soberano cumplen funciones distintas.'},check:{prompt:'¿Qué es el gouvernement?',options:['Órgano intermedio de ejecución','Titular necesario de soberanía','Fuente privada de la ley'],answer:0}},
  {title:'Libertad civil y obediencia a la ley propia',hook:'El pacto transforma libertad natural en libertad civil y moral.',body:'Ser libre políticamente no es hacer cualquier cosa, sino obedecer leyes que uno prescribe como miembro del soberano. La famosa fórmula “forzar a ser libre” expresa coerción para cumplir una obligación general asumida por todos; sigue siendo una tesis problemática que exige distinguir voluntad general de dominación mayoritaria.',relation:['pacto','autolegislación común','ley','libertad civil'],terms:[['liberté civile','','libertad civil'],['liberté morale','','libertad moral'],['obéissance','','obediencia'],['forcer à être libre','','forzar a ser libre']],quote:{original:'on le forcera d’être libre',translation:'«Se lo forzará a ser libre».',source:'Du contrat social I.7',note:'La frase solo se entiende dentro de la tesis de autolegislación del cuerpo soberano.'},example:'La coerción de una ley general que todos se dieron pretende diferir de obedecer caprichos privados de otro.',tip:'Cerrá el sistema preguntando cuándo la voluntad común es realmente general.',discovery:{scenario:'Una ley general obliga también a quien votó en contra, pero fue producida por el procedimiento del cuerpo soberano.',question:'¿Cómo justifica Rousseau esa obligación?',options:['Como obediencia a la ley común de la que el ciudadano es coautor','Como dominación privada','Como derecho del más fuerte'],answer:0,reveal:'La libertad civil se redefine como autolegislación colectiva.'},check:{prompt:'¿Qué relación une libertad y ley?',options:['La libertad civil consiste en obedecer una ley común de la que se es coautor','Toda ley destruye libertad','Solo el gobernante es libre'],answer:0}}
 ]});
})();
